import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'FooterColophon';

  // ---------- BACKDROP ----------
  const width = 6.8;
  const height = 2.0;
  const backdropGeo = new PlaneGeometry(width, height);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(color('#121218'), color('#0b0b10'), uv().y);
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;
  backdropMat.transparent = true;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, 0);
  root.add(backdrop);

  // ---------- HAIRLINE TOP ----------
  const hairlineHeight = 0.006;
  const hairlineGeo = new PlaneGeometry(width, hairlineHeight);
  const hairlineMat = new MeshStandardNodeMaterial();
  hairlineMat.color = new THREE.Color('#23232b');
  hairlineMat.roughness = 0.6;
  hairlineMat.metalness = 0.2;
  hairlineMat.transparent = true;
  const hairlineTop = new Mesh(hairlineGeo, hairlineMat);
  hairlineTop.position.set(0, height / 2 - hairlineHeight / 2, 0.001);
  root.add(hairlineTop);

  // ---------- HAIRLINE BOTTOM ----------
  const hairlineBottom = hairlineTop.clone();
  hairlineBottom.position.set(0, -height / 2 + hairlineHeight / 2, 0.001);
  root.add(hairlineBottom);

  // ---------- WORDMARK ----------
  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.02 * 34,
  });
  const wordmarkX = -width / 2 + 1.0; // left block center
  const wordmarkY = 0.5;
  wordmarkText.position.set(wordmarkX - 1.0, wordmarkY, 0.01);
  root.add(wordmarkText);

  // ---------- ACCENT BAR ----------
  const accentBarGeo = new PlaneGeometry(0.3, 0.02);
  const accentBarMat = new MeshStandardNodeMaterial();
  accentBarMat.color = new THREE.Color('#ff2a38');
  accentBarMat.emissive = new THREE.Color('#ff2a38');
  accentBarMat.emissiveIntensity = 1.4;
  accentBarMat.roughness = 0.6;
  accentBarMat.metalness = 0.2;
  accentBarMat.transparent = true;
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(wordmarkX - 1.0, wordmarkY - 0.2, 0.01);
  root.add(accentBar);

  // ---------- LINK COLUMNS ----------
  const columnWidths = 1.2;
  const gutter = 0.375;
  const leftEdge = -width / 2;
  const firstColX = leftEdge + 2.0 + gutter + columnWidths / 2;
  const secondColX = firstColX + columnWidths + gutter;
  const thirdColX = secondColX + columnWidths + gutter;

  const columns = [
    {
      x: firstColX,
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      x: secondColX,
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      x: thirdColX,
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const linkTimelines = [];

  columns.forEach((col, colIdx) => {
    // Header
    const header = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 0.12 * 9,
    });
    header.position.set(col.x - columnWidths / 2, 0.6, 0.01);
    root.add(header);

    // Links
    col.links.forEach((txt, i) => {
      const link = ctx.fontAtlas.createText(txt, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0,
      });
      const linkY = 0.4 - i * 0.2;
      link.position.set(col.x - columnWidths / 2, linkY, 0.01);
      root.add(link);

      // Hover interaction
      const origColor = new THREE.Color('#e8ecf2');
      const hoverColor = new THREE.Color('#ff2a38');
      const proxy = { t: 0, z: 0 };
      const tl = gsap.timeline({ paused: true });
      tl.to(proxy, {
        t: 1,
        z: 0.02,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: () => {
          link.material.color.lerpColors(origColor, hoverColor, proxy.t);
          link.position.z = proxy.z;
        },
      });
      linkTimelines.push(tl);
      link.userData.handlers = {
        hover: () => tl.play(),
        unhover: () => tl.reverse(),
      };
    });
  });

  // ---------- LEGAL TEXT ----------
  const legal = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0.04 * 9,
    }
  );
  legal.position.set(0, -0.6, 0.01);
  root.add(legal);

  // ---------- OVERALL FADE‑UP ----------
  root.position.y += 0.2;
  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });
  const fadeTl = gsap.timeline();
  fadeTl.to(root.position, { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
  fadeTl.to(
    root,
    {
      onUpdate: () => {
        root.traverse((obj) => {
          if (obj.isMesh) obj.material.opacity = fadeTl.progress();
        });
      },
      duration: 0.5,
    },
    '<'
  );

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // dispose geometries and materials
    backdropGeo.dispose();
    backdropMat.dispose();
    hairlineGeo.dispose();
    hairlineMat.dispose();
    accentBarGeo.dispose();
    accentBarMat.dispose();
    // dispose texts
    root.traverse((obj) => {
      if (obj.isMesh && obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
      if (obj.isMesh && obj.material && obj.material.dispose) obj.material.dispose();
    });
    // kill timelines
    fadeTl.kill();
    linkTimelines.forEach((t) => t.kill());
  };

  return root;
}
